function createDockActions(dockUserPropertiesLabel, undockUserPropertiesLabel) {
	const svgDockIcon = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 16 16">
		<path d="M13,8H12v3H5V4H8V3H4V6H1v9h9V12h3ZM9,14H2V7H4v5H9Z"  fill="#ffb900"/>
		<polygon points="14.854 1.854 14.146 1.146 11 4.293 11 2 10 2 10 6 14 6 14 5 11.707 5 14.854 1.854" fill="#ffb900"/>
	</svg>`;
	
	const svgUndockIcon = `<svg viewBox="0 0 16 16">
		<path d="M13,7H12v4H5V4H9V3H4V6H1v9h9V12h3ZM9,14H2V7H4v5H9Z" fill="#fff"/>
		<polygon points="11 1 11 2 13.293 2 10.146 5.146 10.854 5.854 14 2.707 14 5 15 5 15 1 11 1" fill="#fff"/>
	</svg>`;
	
	const dockIcon = createElement({elemTag: "div", classList: ['dock'], attrs: {innerHTML: svgDockIcon, title: dockUserPropertiesLabel }});
	const undockIcon = createElement({elemTag: "div", classList: ['undock'], attrs: {innerHTML: svgUndockIcon, title: undockUserPropertiesLabel}});	
	
	const dockActionsContainer = createElement({elemTag: "div", classList: ["dock-icon", "undock"], childNodes: [dockIcon, undockIcon]});

	return [dockActionsContainer, (dockUserInfo) => {
			if (!dockUserInfo){
				dockActionsContainer.classList.add("undock");
			}
			else {
				dockActionsContainer.classList.remove("undock");
			}
	}];
}

function createUserInfo(userName, plantKey, plantName) {
	return [
		createElement({elemTag:'span', attrs: {innerText : userName}}),	
		createElement({elemTag:'span', attrs: {innerText : `${plantKey}: ${plantName}`}})
	];
}

function createUserInfoContainer(userInfo, enableClose, onCloseAction) {
	const exfnContentCanvas = document.querySelector(".exfn-content-canvas");
	if (!exfnContentCanvas) {
		return;
	}
	const childNodes = [...userInfo];
	let closeAction;
	if (enableClose){
		closeAction = createElement({elemTag: "div", attrs:{innerHTML: closeIcon}});
		childNodes.push(closeAction);
	}
	const userInfoContainer = createElement({
		elemTag: "div", 
		classList: ["exfn-floating-user-info"], 
		childNodes
	});
	exfnContentCanvas.appendChild(userInfoContainer);
	
	if (enableClose){
		closeAction.addEventListener("click", onCloseAction);
	}
	return (hideUserInfo) => {
		if (hideUserInfo){
			userInfoContainer.classList.add("hidden");
		}
		else {
			userInfoContainer.classList.remove("hidden");
		}
	};
}

function enhanceUserNavigationWithUserInfo(userMenu, userInfo, dockActions, showDockActions) {
	const childNodes = [createUserAvatar()];
	if (showDockActions){
		childNodes.push(dockActions)
	}
	childNodes.push(...userInfo);
	userMenu.prepend(createElement({
		elemTag: "div",
		classList: ['nav-user-avatar'],
		childNodes
	}));
}
