/**
 * @param {string} plantName
 * @param {boolean} showUserFullName
 * @param {boolean} showAlwaysUserProps
 * @param {string} plantLabel
 * @param {string} dockUserPropertiesLabel
 * @param {string} undockUserPropertiesLabel
 * @returns {Promise.<void>}
 */
export async function SetUserInfo(plantName, showUserFullName, showAlwaysUserProps, plantLabel, dockUserPropertiesLabel, undockUserPropertiesLabel) {
	// BEGIN USER CODE
	setTimeout(() => {
		let userName = mx.session.getUserName();
		if (showUserFullName){
			const _fullName = mx.session.getUserObject();
			if (_fullName){
				userName = _fullName.get("FullName") || userName;
			}
		}
		const userInfoConfKey = "exfn_mx_show_user_properties";
		const userMenu = document.querySelector('.region-sidebar .mx-navbar.secondary-menu .mx-navbar-submenu');
		const [dockActions, toggleDockAction] = showAlwaysUserProps ? [null, () => {}] :
			createDockActions(dockUserPropertiesLabel, undockUserPropertiesLabel);

		enhanceUserNavigationWithUserInfo(userMenu, createUserInfo(userName, plantLabel, plantName), dockActions, !showAlwaysUserProps);
		
		let toggleUserInfo;
		const initUserInfo =  () => toggleUserInfo = createUserInfoContainer(
			createUserInfo(userName, plantLabel, plantName), 
			!showAlwaysUserProps,
			() => handleUserInfoVisibilityChange(false)
		);
		const handleUserInfoVisibilityChange = (showUserInfo) => {
			toggleDockAction(showUserInfo);	
			toggleUserInfo(!showUserInfo);
			localStorage.setItem(userInfoConfKey, showUserInfo);
		} 
		const existingConfig = localStorage.getItem(userInfoConfKey);
		if (showAlwaysUserProps || (existingConfig && existingConfig === "true")){
			initUserInfo();
		}
		if(!showAlwaysUserProps){
			dockActions.addEventListener("click", (e) => {
				e.preventDefault();
				e.stopPropagation();
				if (!toggleUserInfo){
					initUserInfo(); 
				}
				handleUserInfoVisibilityChange(dockActions.classList.contains("undock"));
			});
		}
	}, 0);
	// END USER CODE
}
